1	import { defineHook } from "../lib/hook";
2	import { PersistedRecord } from "../lib/persisted_record";
3	import { attachScrubber, fractionAt } from "../lib/scrubber";
4	import { scrollFollow } from "../lib/scroll_follow";
5	import { readerSettings } from "../lib/reader_settings_store";
6	import { cycleOption } from "../lib/cycle_option";
7	import { type WordTiming, parseWordTimings } from "../lib/types";
8	import { attachWordMenu } from "./word_menu";
9	
10	interface AudioPlayerDataset {
11	  audioUrl: string;
12	  timingsUrl: string;
13	  initialPosition?: string;
14	}
15	
16	interface PlayerPrefs {
17	  readonly speed: number;
18	  readonly volume: number;
19	  readonly collapsed: boolean;
20	}
21	
22	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
23	  speed: 1,
24	  volume: 1,
25	  collapsed: false,
26	});
27	
28	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
29	
30	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
31	
32	const POSITION_REPORT_INTERVAL_MS = 5000;
33	const SKIP_SECONDS = 10;
34	const AUTO_SCROLL_GRACE_MS = 800;
35	const AUTO_PLAY_HANDOFF_KEY = "readaloud-audio-autoplay";
36	
37	function coercePlayerPrefs(raw: unknown): Partial<PlayerPrefs> {
38	  if (!raw || typeof raw !== "object") return {};
39	  const r = raw as Record<string, unknown>;
40	  const out: { -readonly [K in keyof PlayerPrefs]?: PlayerPrefs[K] } = {};
41	  if (typeof r.speed === "number") out.speed = r.speed;
42	  if (typeof r.volume === "number") out.volume = r.volume;
43	  if (typeof r.collapsed === "boolean") out.collapsed = r.collapsed;
44	  return out;
45	}
46	
47	function migrateLegacyPlayerPrefs(): void {
48	  if (localStorage.getItem(PLAYER_PREFS_KEY) !== null) return;
49	  const legacySpeed = localStorage.getItem("readaloud-playback-speed");
50	  const legacyVolume = localStorage.getItem("readaloud-volume");
51	  const legacyCollapsed = localStorage.getItem("readaloud-player-collapsed");
52	  if (legacySpeed === null && legacyVolume === null && legacyCollapsed === null)
53	    return;
54	  const migrated: PlayerPrefs = {
55	    speed:
56	      legacySpeed !== null
57	        ? Number.parseFloat(legacySpeed)
58	        : PLAYER_PREFS_DEFAULTS.speed,
59	    volume:
60	      legacyVolume !== null
61	        ? Number.parseFloat(legacyVolume)
62	        : PLAYER_PREFS_DEFAULTS.volume,
63	    collapsed: legacyCollapsed === "true",
64	  };
65	  localStorage.setItem(PLAYER_PREFS_KEY, JSON.stringify(migrated));
66	}
67	
68	migrateLegacyPlayerPrefs();
69	const playerPrefs = new PersistedRecord<PlayerPrefs>(
70	  PLAYER_PREFS_KEY,
71	  PLAYER_PREFS_DEFAULTS,
72	  coercePlayerPrefs,
73	);
74	
75	function findActiveWord(
76	  timings: ReadonlyArray<WordTiming>,
77	  ms: number,
78	): number {
79	  let idx = -1;
80	  let lo = 0;
81	  let hi = timings.length - 1;
82	  while (lo <= hi) {
83	    const mid = (lo + hi) >>> 1;
84	    const t = timings[mid];
85	    if (!t) break;
86	    if (ms >= t.startMs && ms < t.endMs) {
87	      idx = mid;
88	      break;
89	    } else if (ms < t.startMs) {
90	      hi = mid - 1;
91	    } else {
92	      idx = mid;
93	      lo = mid + 1;
94	    }
95	  }
96	  if (idx >= 0 && idx < timings.length - 1) {
97	    const next = timings[idx + 1];
98	    if (next && ms >= next.startMs) idx += 1;
99	  }
100	  return idx;
101	}
102	
103	function formatTime(secs: number): string {
104	  if (!Number.isFinite(secs) || secs < 0) return "0:00";
105	  const m = Math.floor(secs / 60);
106	  const s = Math.floor(secs % 60);
107	  return `${m}:${s < 10 ? "0" : ""}${s}`;
108	}
109	
110	export const AudioPlayerHook = defineHook<HTMLDivElement, AudioPlayerDataset>(
111	  (ctx) => {
112	    const audio = document.getElementById("audio-element");
113	    const playPauseBtn = document.getElementById("play-pause-btn");
114	    const timeDisplay = document.getElementById("time-display");
115	    const textContainer = document.getElementById("chapter-text");
116	    const resyncBtn = document.getElementById("resync-btn");
117	    const speedBadge = document.getElementById("speed-badge");
118	
119	    if (!(audio instanceof HTMLAudioElement) || !playPauseBtn) {
120	      console.error("AudioPlayer: required DOM elements missing");
121	      return;
122	    }
123	
124	    let timings: ReadonlyArray<WordTiming> = [];
125	    let currentWordIndex = -1;
126	    let lastReportedMs = -1;
127	    let rafId: number | undefined;
128	    let wordMenuCleanup: (() => void) | undefined;
129	    let intersectionObserver: IntersectionObserver | undefined;
130	
131	    const applyAudioPrefs = (): void => {
132	      const p = playerPrefs.get();
133	      audio.playbackRate = p.speed;
134	      audio.volume = p.volume;
135	      updateSpeedBadge(p.speed);
136	    };
137	
138	    const updateTimeDisplay = (): void => {
139	      if (!timeDisplay) return;
140	      timeDisplay.textContent = `${formatTime(audio.currentTime)} / ${formatTime(audio.duration)}`;
141	    };
142	
143	    const updateSpeedBadge = (speed: number): void => {
144	      if (!speedBadge) return;
145	      speedBadge.textContent = speed === 1 ? "1x" : `${speed}x`;
146	    };
147	
148	    const setSpeed = (speed: number): void => {
149	      playerPrefs.set({ speed });
150	      audio.playbackRate = speed;
151	      updateSpeedBadge(speed);
152	    };
153	
154	    const cycleSpeed = (direction: "up" | "down"): void => {
155	      const closest = SPEEDS.reduce((best, s) =>
156	        Math.abs(s - audio.playbackRate) < Math.abs(best - audio.playbackRate)
157	          ? s
158	          : best,
159	      );
160	      setSpeed(cycleOption(SPEEDS, closest, direction));
161	    };
162	
163	    const togglePlayback = (): void => {
164	      if (audio.paused) audio.play();
165	      else audio.pause();
166	    };
167	
168	    const seekToWordIndex = (idx: number): void => {
169	      const t = timings[idx];
170	      if (!t) return;
171	      audio.currentTime = t.startMs / 1000;
172	      if (audio.paused) audio.play();
173	    };
174	
175	    // Word highlighting with auto-scroll
176	    const highlightWord = (ms: number): void => {
177	      if (!textContainer || timings.length === 0) return;
178	      const idx = findActiveWord(timings, ms);
179	      if (idx === currentWordIndex) return;
180	
181	      if (currentWordIndex >= 0) {
182	        const old = textContainer.querySelector<HTMLElement>(
183	          `[data-word-index="${currentWordIndex}"]`,
184	        );
185	        old?.classList.remove("word-active");
186	        old?.classList.add("word-spoken");
187	      }
188	
189	      if (idx >= 0) {
190	        const next = textContainer.querySelector<HTMLElement>(
191	          `[data-word-index="${idx}"]`,
192	        );
193	        if (next) {
194	          next.classList.add("word-active");
195	          next.classList.remove("word-spoken");
196	
197	          if (!scrollFollow.get().autoScrollPaused) {
198	            scrollFollow.beginAutoScroll(AUTO_SCROLL_GRACE_MS);
199	            next.scrollIntoView({ behavior: "smooth", block: "center" });
200	            if (intersectionObserver) {
201	              intersectionObserver.disconnect();
202	              intersectionObserver.observe(next);
203	            }
204	          }
205	        }
206	      }
207	
208	      if (idx > currentWordIndex) {
209	        for (let i = Math.max(0, currentWordIndex); i < idx; i++) {
210	          const el = textContainer.querySelector<HTMLElement>(
211	            `[data-word-index="${i}"]`,
212	          );
213	          if (el) {
214	            el.classList.remove("word-active");
215	            el.classList.add("word-spoken");
216	          }
217	        }
218	      } else if (idx >= 0 && idx < currentWordIndex) {
219	        for (let i = idx + 1; i <= currentWordIndex; i++) {
220	          const el = textContainer.querySelector<HTMLElement>(
221	            `[data-word-index="${i}"]`,
222	          );
223	          if (el) el.classList.remove("word-spoken", "word-active");
224	        }
225	      }
226	
227	      currentWordIndex = idx;
228	    };
229	
230	    const startHighlightLoop = (): void => {
231	      const tick = (): void => {
232	        if (!audio.paused) {
233	          highlightWord(audio.currentTime * 1000);
234	          rafId = requestAnimationFrame(tick);
235	        }
236	      };
237	      rafId = requestAnimationFrame(tick);
238	    };
239	
240	    const stopHighlightLoop = (): void => {
241	      if (rafId !== undefined) {
242	        cancelAnimationFrame(rafId);
243	        rafId = undefined;
244	      }
245	    };
246	
247	    // Initial setup
248	    if (playerPrefs.get().collapsed) ctx.el.classList.add("collapsed");
249	
250	    const volSlider = ctx.el.querySelector<HTMLInputElement>(
251	      "[data-volume-slider]",
252	    );
253	    if (volSlider) volSlider.value = String(playerPrefs.get().volume);
254	    updateSpeedBadge(playerPrefs.get().speed);
255	
256	    // The <audio> element has phx-update="ignore" so it's preserved across
257	    // same-LV navigation (auto-next chapter). Reassigning .src alone doesn't
258	    // reliably refetch on iOS Safari — call load() explicitly to invoke the
259	    // resource selection algorithm and reset the element's media state.
260	    audio.src = ctx.dataset.audioUrl;
261	    audio.load();
262	    applyAudioPrefs();
263	
264	    ctx.on(audio, "loadedmetadata", () => {
265	      applyAudioPrefs();
266	      updateTimeDisplay();
267	    });
268	    ctx.on(audio, "durationchange", updateTimeDisplay);
269	
270	    // Word timings
271	    fetch(ctx.dataset.timingsUrl)
272	      .then((r) => r.json())
273	      .then((data: unknown) => {
274	        timings = parseWordTimings(data);
275	        if (textContainer) wordMenuCleanup = attachWordMenu(textContainer);
276	      })
277	      .catch((err: unknown) =>
278	        console.error("AudioPlayer: failed to load timings", err),
279	      );
280	
281	    // Restore initial position
282	    const initialMs = Number.parseInt(ctx.dataset.initialPosition ?? "0", 10);
283	    if (initialMs > 0) {
284	      ctx.on(
285	        audio,
286	        "loadedmetadata",
287	        () => {
288	          audio.currentTime = initialMs / 1000;
289	        },
290	        { once: true },
291	      );
292	    }
293	
294	    // Auto-play handoff: if the previous chapter ended with auto-next-chapter
295	    // enabled, the ended handler stashed a flag in sessionStorage. Consume it
296	    // and start playback once metadata is loaded.
297	    if (sessionStorage.getItem(AUTO_PLAY_HANDOFF_KEY) === "1") {
298	      sessionStorage.removeItem(AUTO_PLAY_HANDOFF_KEY);
299	      ctx.on(
300	        audio,
301	        "loadedmetadata",
302	        () => {
303	          audio.play().catch((err: unknown) => {
304	            console.warn("AudioPlayer: auto-play blocked by browser", err);
305	          });
306	        },
307	        { once: true },
308	      );
309	    }
310	
311	    // Controls
312	    ctx.on(playPauseBtn, "click", togglePlayback);
313	
314	    const skipBack = ctx.el.querySelector<HTMLElement>("[data-skip-back]");
315	    const skipFwd = ctx.el.querySelector<HTMLElement>("[data-skip-forward]");
316	    if (skipBack) {
317	      ctx.on(skipBack, "click", () => {
318	        audio.currentTime = Math.max(0, audio.currentTime - SKIP_SECONDS);
319	      });
320	    }
321	    if (skipFwd) {
322	      ctx.on(skipFwd, "click", () => {
323	        const max = Number.isFinite(audio.duration)
324	          ? audio.duration
325	          : Number.POSITIVE_INFINITY;
326	        audio.currentTime = Math.min(max, audio.currentTime + SKIP_SECONDS);
327	      });
328	    }
329	
330	    const collapseToggle = ctx.el.querySelector<HTMLElement>(
331	      "[data-collapse-toggle]",
332	    );
333	    if (collapseToggle) {
334	      ctx.on(collapseToggle, "click", () => {
335	        const isCollapsed = ctx.el.classList.toggle("collapsed");
336	        playerPrefs.set({ collapsed: isCollapsed });
337	      });
338	    }
339	
340	    if (volSlider) {
341	      ctx.on(volSlider, "input", () => {
342	        const vol = Number.parseFloat(volSlider.value);
343	        audio.volume = vol;
344	        playerPrefs.set({ volume: vol });
345	      });
346	    }
347	
348	    // Scrubbers (main + mini)
349	    const scrubMain = ctx.el.querySelector<HTMLElement>("[data-scrubber]");
350	    const scrubMini = ctx.el.querySelector<HTMLElement>("[data-scrubber-mini]");
351	    const seekToFraction = (f: number): void => {
352	      if (Number.isFinite(audio.duration))
353	        audio.currentTime = f * audio.duration;
354	    };
355	    for (const sc of [scrubMain, scrubMini]) {
356	      if (!sc) continue;
357	      const dispose = attachScrubber<number>({
358	        el: sc,
359	        indexAt: (clientX) => fractionAt(sc, clientX),
360	        preview: () => {},
361	        commit: seekToFraction,
362	      });
363	      ctx.onDestroy(dispose);
364	    }
365	
366	    // Time updates: progress bars + time display + position report
367	    ctx.on(audio, "timeupdate", () => {
368	      if (!audio.duration) return;
369	      const pct = (audio.currentTime / audio.duration) * 100;
370	      const fill = ctx.el.querySelector<HTMLElement>("[data-progress-fill]");
371	      if (fill) fill.style.width = `${pct}%`;
