1	import { describe, it, before, after } from "node:test";
2	import assert from "node:assert";
3	import {
4		setup,
5		teardown,
6		openReader,
7		sleep,
8		BASE_URL,
9		BOOK_ID,
10	} from "../helpers.js";
11	
12	describe("Accidental Navigation Popup", () => {
13		let browser, page, chapters;
14	
15		before(async () => {
16			({ browser, page } = await setup());
17	
18			// First, open a later chapter to establish reading progress
19			const { chapterId: firstChapterId } = await openReader(page);
20	
21			// Get all chapters from the chapter bar data
22			chapters = await page.evaluate(() => {
23				const bar = document.getElementById("chapter-bar");
24				return bar ? JSON.parse(bar.dataset.chapters) : [];
25			});
26	
27			if (chapters.length < 3) {
28				console.log(
29					"  (book has fewer than 3 chapters — some tests will be skipped)",
30				);
31			}
32		});
33	
34		after(async () => {
35			await teardown(browser);
36		});
37	
38		it("no popup on initial page load with nav=internal", async () => {
39			// Navigate to first chapter with ?nav=internal
40			const ch = chapters[0];
41			if (!ch) return;
42	
43			await page.goto(`${BASE_URL}/books/${BOOK_ID}/read/${ch.id}?nav=internal`, {
44				waitUntil: "networkidle2",
45			});
46			await sleep(500);
47	
48			const modal = await page.$(".modal.modal-open");
49			assert.strictEqual(modal, null, "No popup should appear with nav=internal");
50		});
51	
52		it("popup appears when navigating backward without nav=internal", async () => {
53			if (chapters.length < 3) return;
54	
55			// First, establish progress at a later chapter (e.g., chapter 3)
56			const laterChapter = chapters[Math.min(2, chapters.length - 1)];
57			await page.goto(
58				`${BASE_URL}/books/${BOOK_ID}/read/${laterChapter.id}?nav=internal`,
59				{ waitUntil: "networkidle2" },
60			);
61			await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
62			await sleep(1000); // Wait for progress to save
63	
64			// Now navigate to chapter 1 WITHOUT nav=internal (simulating stale tab)
65			const firstChapter = chapters[0];
66			await page.goto(`${BASE_URL}/books/${BOOK_ID}/read/${firstChapter.id}`, {
67				waitUntil: "networkidle2",
68			});
69			await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
70			await sleep(500);
71	
72			const modal = await page.$(".modal.modal-open");
73			assert.ok(modal, "Conflict popup should appear when navigating backward");
74		});
75	
76		it("popup shows correct chapter information", async () => {
77			const modal = await page.$(".modal.modal-open");
78			if (!modal) return; // skip if popup didn't show (from previous test)
79	
80			const modalText = await page.$eval(".modal-box", (el) => el.textContent);
81			assert.ok(
82				modalText.includes("last reading position"),
83				"Modal should mention last reading position",
84			);
85		});
86	
87		it("'Stay' button dismisses popup and stays on current chapter", async () => {
88			const modal = await page.$(".modal.modal-open");
89			if (!modal) return;
90	
91			// Get current URL before clicking Stay
92			const urlBefore = page.url();
93	
94			// Click the "Stay" button (btn-ghost)
95			await page.click(".modal-action .btn-ghost");
96			await sleep(500);
97	
98			// Modal should be gone
99			const modalAfter = await page.$(".modal.modal-open");
100			assert.strictEqual(
101				modalAfter,
102				null,
103				"Modal should dismiss after clicking Stay",
104			);
105	
106			// URL should not change (stayed on same chapter)
107			const urlAfter = page.url();
108			assert.ok(
109				urlAfter.includes(
110					urlBefore.split("?")[0].split("/read/")[1]?.split("/")[0] || "",
111				),
112				"Should stay on the same chapter",
113			);
114		});
115	
116		it("'Go to' button navigates to the conflict chapter", async () => {
117			if (chapters.length < 3) return;
118	
119			// Re-trigger the conflict: go to later chapter, then navigate back without nav=internal
120			const laterChapter = chapters[Math.min(2, chapters.length - 1)];
121			await page.goto(
122				`${BASE_URL}/books/${BOOK_ID}/read/${laterChapter.id}?nav=internal`,
123				{ waitUntil: "networkidle2" },
124			);
125			await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
126			await sleep(1000);
127	
128			const firstChapter = chapters[0];
129			await page.goto(`${BASE_URL}/books/${BOOK_ID}/read/${firstChapter.id}`, {
130				waitUntil: "networkidle2",
131			});
132			await page.waitForSelector("[data-phx-session]", { timeout: 10000 });
133			await sleep(500);
134	
135			const modal = await page.$(".modal.modal-open");
136			if (!modal) {
137				console.log("  (skipped: popup didn't appear)");
138				return;
139			}
140	
141			// Click "Go to" button (btn-primary)
142			await page.click(".modal-action .btn-primary");
143			await sleep(1000);
144	
145			// Should have navigated to the later chapter
146			const newUrl = page.url();
147			assert.ok(
148				newUrl.includes(`/read/${laterChapter.id}`),
149				`Should navigate to chapter ${laterChapter.id}, got URL: ${newUrl}`,
150			);
151		});
